<template>
  <q-page padding>
    <div class="row items-center q-mb-md"><div><div class="text-h5">Pago de salarios</div><div class="text-caption text-grey-7">Planillas, pagos y asientos de salarios</div></div><q-space/><q-btn v-if="auth.tienePermiso('planilla.crear')" color="primary" icon="add" label="Nueva planilla" @click="abrirPlanilla"/></div>
    <q-banner v-if="error&&!paymentDialog" class="bg-red-1 text-red q-mb-md" rounded>{{ error }}</q-banner><q-banner v-if="mensaje" class="bg-blue-1 text-blue-10 q-mb-md" rounded>{{ mensaje }}</q-banner>
    <q-card class="opti-card"><q-table :rows="planillas" :columns="columns" row-key="id" :loading="cargando" no-data-label="No hay planillas registradas">
      <template #body-cell-bruto="p"><q-td :props="p">{{ dinero(p.value) }}</q-td></template><template #body-cell-deducciones="p"><q-td :props="p">{{ dinero(p.value) }}</q-td></template><template #body-cell-liquido="p"><q-td :props="p">{{ dinero(p.value) }}</q-td></template>
      <template #body-cell-estado="p"><q-td :props="p"><q-badge :color="p.value==='CONTABILIZADA'?'positive':p.value==='APROBADA'?'orange':'grey'">{{ p.value }}</q-badge></q-td></template>
      <template #body-cell-aportes="p"><q-td :props="p">{{ dinero(p.value) }}</q-td></template>
      <template #body-cell-acciones="p"><q-td :props="p"><q-btn dense flat color="secondary" icon="table_view" label="Ver detalle" @click="verDetalle(p.row)"/><q-btn v-if="p.row.estado==='BORRADOR'&&auth.tienePermiso('planilla.aprobar')" dense flat color="primary" icon="send" label="Enviar" :loading="enviando===p.row.id" @click="enviar(p.row)"/><q-btn v-if="p.row.estado==='CONTABILIZADA'&&auth.tienePermiso('planilla.pagar')" dense flat color="positive" icon="payments" label="Registrar pago" @click="abrirPago(p.row)"/></q-td></template>
    </q-table></q-card>
    <q-dialog v-model="dialog"><q-card style="width:1050px;max-width:96vw"><q-card-section class="row items-center"><div class="text-h6">Nueva planilla mensual</div><q-space/><q-btn v-close-popup flat round icon="close"/></q-card-section>
      <q-card-section class="row q-col-gutter-sm"><div class="col-12 col-sm-3"><q-input v-model="form.codigo" label="Código de planilla (opcional)" :placeholder="ejemploCodigo" hint="Ejemplo: PL-202610-0001. Déjalo vacío para que se genere automáticamente." persistent-hint outlined dense/></div><div class="col-12 col-sm-3"><q-input v-model="form.periodo" type="month" label="Mes de pago" outlined dense/></div><div class="col-12 col-sm-3"><q-input v-model="form.fecha_pago" type="date" label="Fecha de pago" outlined dense/></div><div class="col-12 col-sm-3"><q-select v-model="form.sucursal_id" :options="sucursales" option-value="id" option-label="nombre" emit-value map-options label="Sucursal" outlined dense clearable/></div><div class="col-12"><q-select v-model="form.periodo_id" :options="periodos" option-value="id" :option-label="p=>String(p.anio)" emit-value map-options label="Período contable" outlined dense/></div></q-card-section>
      <q-card-section><div class="row items-center q-mb-sm"><div class="text-subtitle1">Empleados y percepciones/deducciones</div><q-space/><q-btn flat color="primary" icon="add" label="Agregar empleado" @click="form.detalles.push(lineaVacia())"/></div>
        <div v-for="(line,i) in form.detalles" :key="i" class="q-pa-sm q-mb-sm rounded-borders" style="border:1px solid var(--opti-border)">
          <div class="row q-col-gutter-sm items-center"><div class="col-10 col-md-4"><q-select v-model="line.empleado_id" :options="empleadosSucursal" option-value="id" :option-label="e=>`${e.codigo} · ${e.nombres} ${e.apellidos}`" emit-value map-options label="Seleccionar empleado" :hint="form.sucursal_id ? 'Solo empleados activos de la sucursal seleccionada' : 'Selecciona primero una sucursal'" :disable="!form.sucursal_id" outlined dense @update:model-value="line.dias_trabajados=30"/></div><div class="col-5 col-md-2"><q-input v-model.number="line.dias_trabajados" type="number" min="1" max="31" label="Días trabajados" outlined dense/></div><div class="col-5 col-md-2 text-caption text-grey-7">Salario base {{ dinero(salarioEmpleado(line.empleado_id)) }} · Devengado {{ dinero(salarioPorDias(line)) }}</div><div class="col-2 col-md-1"><q-btn flat round color="negative" icon="delete" :disable="form.detalles.length===1" @click="form.detalles.splice(i,1)"/></div><div class="col-12 col-md-3"><q-select v-model="line.cuenta_gasto_codigo" :options="cuentasGasto" option-value="codigo" :option-label="c=>`${c.codigo} · ${c.nombre}`" emit-value map-options label="Área / cuenta del gasto" outlined dense/></div></div>
          <div class="text-caption text-primary q-mt-sm">Percepciones</div><div class="row q-col-gutter-sm"><div class="col-6 col-md-2"><q-input v-model.number="line.horas_extra" type="number" min="0" step="0.01" label="Horas extra ($)" outlined dense/></div><div class="col-6 col-md-2"><q-input v-model.number="line.bonificaciones" type="number" min="0" step="0.01" label="Bonificaciones ($)" outlined dense/></div><div class="col-6 col-md-2"><q-input v-model.number="line.comisiones" type="number" min="0" step="0.01" label="Comisiones ($)" outlined dense/></div><div class="col-12 col-md-3 text-caption self-center">Subtotal devengado: <b>{{ dinero(bruto(line)) }}</b></div></div>
          <div class="text-caption text-primary q-mt-sm">Descuentos al empleado</div><div class="row q-col-gutter-sm"><div class="col-6 col-md-2"><q-input v-model.number="line.deduccion_isss" type="number" min="0" step="0.01" label="ISSS retenido ($)" outlined dense/></div><div class="col-6 col-md-2"><q-input v-model.number="line.deduccion_afp" type="number" min="0" step="0.01" label="AFP retenida ($)" outlined dense/></div><div class="col-6 col-md-2"><q-input v-model.number="line.deduccion_renta" type="number" min="0" step="0.01" label="ISR / renta ($)" outlined dense/></div><div class="col-6 col-md-2"><q-input v-model.number="line.otras_deducciones" type="number" min="0" step="0.01" label="Otros descuentos ($)" outlined dense/></div><div class="col-12 col-md-3 text-caption self-center">Líquido: <b>{{ dinero(liquido(line)) }}</b></div></div>
          <div class="text-caption text-primary q-mt-sm">Aportes patronales que paga la empresa</div><div class="row q-col-gutter-sm"><div class="col-6 col-md-2"><q-input v-model.number="line.isss_patronal" type="number" min="0" step="0.01" label="ISSS patronal ($)" outlined dense/></div><div class="col-6 col-md-2"><q-input v-model.number="line.afp_patronal" type="number" min="0" step="0.01" label="AFP patronal ($)" outlined dense/></div></div>
        </div><div class="text-right text-subtitle2">Devengado {{ dinero(totalBruto) }} · Descuentos {{ dinero(totalDeducciones) }} · Neto a pagar {{ dinero(totalLiquido) }} · Aportes patronales {{ dinero(totalPatronal) }}</div>
      </q-card-section><q-card-actions align="right"><q-btn flat label="Cancelar" v-close-popup/><q-btn color="primary" label="Guardar borrador" :loading="guardando" @click="guardar"/></q-card-actions></q-card></q-dialog>
    <q-dialog v-model="detailDialog"><q-card style="width:1100px;max-width:96vw"><q-card-section class="row items-center"><div class="text-h6">Detalle de planilla {{ detalleSeleccionado?.planilla?.codigo }}</div><q-space/><q-btn v-if="detalleSeleccionado?.planilla?.asiento_id" flat color="primary" icon="menu_book" label="Abrir asiento en Libro Diario" @click="irAlAsiento(detalleSeleccionado.planilla.asiento_id)"/><q-btn v-close-popup flat round icon="close"/></q-card-section><q-card-section><q-table :rows="detalleSeleccionado?.detalles||[]" :columns="detalleColumns" row-key="codigo" :loading="cargandoDetalle" :pagination="{rowsPerPage:0}" :rows-per-page-options="[0]" no-data-label="Sin empleados"><template #body-cell-bruto="p"><q-td :props="p">{{ dinero(p.value) }}</q-td></template><template #body-cell-deducciones="p"><q-td :props="p">{{ dinero(p.value) }}</q-td></template><template #body-cell-liquido="p"><q-td :props="p">{{ dinero(p.value) }}</q-td></template><template #body-cell-patronales="p"><q-td :props="p">{{ dinero(p.value) }}</q-td></template></q-table></q-card-section></q-card></q-dialog>
    <q-dialog v-model="paymentDialog"><q-card style="width:560px;max-width:95vw"><q-card-section class="text-h6">Registrar desembolso de salarios</q-card-section><q-card-section class="q-gutter-sm"><q-banner v-if="paymentError" class="bg-red-1 text-red" rounded>{{ paymentError }}</q-banner><div>Planilla <b>{{ selectedPayroll?.codigo }}</b> · período <b>{{ selectedPayroll?.periodo }}</b> · monto neto <b>{{ dinero(selectedPayroll?.liquido) }}</b></div><q-input v-model="payment.fecha_pago" type="date" label="Fecha de pago" outlined dense @update:model-value="actualizarPeriodoPago"/><q-select v-model="payment.periodo_id" :options="periodos" option-value="id" :option-label="p=>String(p.anio)" emit-value map-options label="Período contable" outlined dense/><q-select v-model="payment.cuenta_pago_codigo" :options="cuentasPago" option-value="codigo" :option-label="c=>`${c.codigo} · ${c.nombre}`" emit-value map-options label="Cuenta de caja o bancos" outlined dense/></q-card-section><q-card-actions align="right"><q-btn flat label="Cancelar" v-close-popup/><q-btn color="positive" label="Crear asiento pendiente" :loading="guardando" :disable="!payment.periodo_id" @click="guardarPago"/></q-card-actions></q-card></q-dialog>
  </q-page>
</template>
<script setup>
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRouter} from 'vue-router'
import {useQuasar} from 'quasar'
import {useAuthStore} from '@/stores/auth.js'
import {api} from '@/services/api.js'
import {operacionesService} from '@/services/operacionesService.js'
const $q=useQuasar(),auth=useAuthStore(),router=useRouter();const planillas=ref([]),empleados=ref([]),sucursales=ref([]),periodos=ref([]),cuentasGasto=ref([]),error=ref(''),paymentError=ref(''),mensaje=ref(''),cargando=ref(false),guardando=ref(false),enviando=ref(null),dialog=ref(false),detailDialog=ref(false),detalleSeleccionado=ref(null),cargandoDetalle=ref(false)
const hoy=()=>new Date().toLocaleDateString('sv-SE'),lineaVacia=()=>({empleado_id:null,dias_trabajados:30,cuenta_gasto_codigo:'4.1.3.01',horas_extra:0,bonificaciones:0,comisiones:0,deduccion_isss:0,deduccion_afp:0,deduccion_renta:0,otras_deducciones:0,isss_patronal:0,afp_patronal:0}),nuevo=()=>({codigo:'',periodo:new Date().toISOString().slice(0,7),fecha_pago:hoy(),sucursal_id:null,periodo_id:null,detalles:[lineaVacia()]})
let refreshPlanillasTimer=null
const form=ref(nuevo()),paymentDialog=ref(false),selectedPayroll=ref(null),cuentasPago=ref([]),payment=ref({fecha_pago:hoy(),periodo_id:null,cuenta_pago_codigo:'1.1.1.01'}),columns=[{name:'codigo',label:'Código',field:'codigo'},{name:'periodo',label:'Período',field:'periodo'},{name:'fecha_pago',label:'Pago',field:'fecha_pago'},{name:'empleados',label:'Empleados',field:'empleados'},{name:'bruto',label:'Devengado',field:'bruto',align:'right'},{name:'deducciones',label:'Descuentos',field:'deducciones',align:'right'},{name:'aportes',label:'Aportes empresa',field:'aportes_patronales',align:'right'},{name:'liquido',label:'Neto',field:'liquido',align:'right'},{name:'estado',label:'Estado',field:'estado'},{name:'acciones',label:'Acciones',field:'id',align:'right'}]
const dinero=v=>new Intl.NumberFormat('es-SV',{style:'currency',currency:'USD'}).format(Number(v)||0),salarioEmpleado=id=>Number(empleados.value.find(e=>e.id===id)?.salario_base||0),salarioPorDias=l=>salarioEmpleado(l.empleado_id)*(Number(l.dias_trabajados)||0)/30,bruto=l=>salarioPorDias(l)+(Number(l.horas_extra)||0)+(Number(l.bonificaciones)||0)+(Number(l.comisiones)||0),deducciones=l=>['deduccion_isss','deduccion_afp','deduccion_renta','otras_deducciones'].reduce((s,k)=>s+(Number(l[k])||0),0),liquido=l=>bruto(l)-deducciones(l),totalBruto=computed(()=>form.value.detalles.reduce((s,l)=>s+bruto(l),0)),totalDeducciones=computed(()=>form.value.detalles.reduce((s,l)=>s+deducciones(l),0)),totalLiquido=computed(()=>totalBruto.value-totalDeducciones.value),totalPatronal=computed(()=>form.value.detalles.reduce((s,l)=>s+(Number(l.isss_patronal)||0)+(Number(l.afp_patronal)||0),0))
const ejemploCodigo=computed(()=>`Ej.: PL-${String(form.value.periodo||'').replace('-','')||'202610'}-0001`)
const empleadosSucursal=computed(()=>form.value.sucursal_id?empleados.value.filter(e=>Number(e.sucursal_id)===Number(form.value.sucursal_id)):[])
watch(()=>form.value.sucursal_id,(sucursalId)=>{
  if(!dialog.value)return
  const idsPermitidos=new Set(empleados.value.filter(e=>Number(e.sucursal_id)===Number(sucursalId)).map(e=>e.id))
  form.value.detalles.forEach(line=>{if(line.empleado_id&&!idsPermitidos.has(line.empleado_id))line.empleado_id=null})
})
const detalleColumns=[{name:'empleado',label:'Empleado',field:r=>`${r.codigo} · ${r.nombres} ${r.apellidos}`},{name:'dias',label:'Días',field:'dias_trabajados'},{name:'salario',label:'Salario base',field:'salario_base',format:dinero},{name:'bruto',label:'Devengado',field:'bruto'},{name:'isss',label:'ISSS',field:'deduccion_isss',format:dinero},{name:'afp',label:'AFP',field:'deduccion_afp',format:dinero},{name:'renta',label:'ISR / renta',field:'deduccion_renta',format:dinero},{name:'deducciones',label:'Otros',field:'otras_deducciones',format:dinero},{name:'liquido',label:'Neto',field:'liquido'},{name:'patronales',label:'Aportes patronales',field:r=>Number(r.isss_patronal||0)+Number(r.afp_patronal||0)}]
async function cargar(){cargando.value=true;error.value='';try{const [p,e,s,per,a,g]=await Promise.all([operacionesService.planillas(),operacionesService.empleados(),api.get('/api/sucursales'),api.get('/api/periodos'),api.get('/api/cuentas?q=1.1.'),api.get('/api/cuentas?q=4.1.')]);planillas.value=p.planillas;empleados.value=e.empleados.filter(x=>x.estado==='ACTIVO');sucursales.value=s.sucursales;periodos.value=per.periodos.filter(x=>x.estado==='ABIERTO');const padres=new Set(a.cuentas.map(x=>x.codigo_padre));cuentasPago.value=a.cuentas.filter(x=>(x.codigo.startsWith('1.1.1.')||x.codigo.startsWith('1.1.2.'))&&!padres.has(x.codigo));const padresGasto=new Set(g.cuentas.map(x=>x.codigo_padre));cuentasGasto.value=g.cuentas.filter(x=>['4.1.1.09','4.1.3.01','4.1.4.01'].includes(x.codigo)&&!padresGasto.has(x.codigo))}catch(e){error.value=e.message}finally{cargando.value=false}}
function abrirPlanilla(){form.value=nuevo();form.value.periodo_id=periodos.value[0]?.id||null;form.value.sucursal_id=auth.usuario?.sucursal_id||sucursales.value[0]?.id||null;dialog.value=true}
async function guardar(){error.value='';if(!form.value.sucursal_id){error.value='Selecciona la sucursal de la planilla.';return}if(!form.value.periodo_id||!form.value.detalles.length){error.value='Selecciona un período contable e incluye al menos un empleado.';return}const sinEmpleado=form.value.detalles.findIndex(x=>!x.empleado_id);if(sinEmpleado>=0){error.value=`Selecciona el empleado de la línea ${sinEmpleado+1}.`;return}const otroCentro=form.value.detalles.findIndex(x=>!empleadosSucursal.value.some(e=>e.id===x.empleado_id));if(otroCentro>=0){error.value=`El empleado de la línea ${otroCentro+1} no pertenece a la sucursal seleccionada.`;return}const invalido=form.value.detalles.findIndex(x=>deducciones(x)>bruto(x));if(invalido>=0){error.value=`Los descuentos superan el salario devengado de la línea ${invalido+1}.`;return}guardando.value=true;try{await operacionesService.crearPlanilla(form.value);dialog.value=false;mensaje.value='Planilla guardada como borrador.';await cargar();$q.notify({type:'positive',message:'Planilla guardada como borrador'})}catch(e){error.value=e.message}finally{guardando.value=false}}
async function enviar(row){error.value='';enviando.value=row.id;try{const r=await operacionesService.enviarPlanilla(row.id);mensaje.value=`Asiento ${r.asiento_codigo} pendiente de aprobación. Apruébalo en Control; también puedes abrirlo con “Ver asiento”.`;$q.notify({type:'positive',message:`Asiento ${r.asiento_codigo} generado`});await cargar()}catch(e){error.value=e.message}finally{enviando.value=null}}
async function verDetalle(row){error.value='';cargandoDetalle.value=true;detailDialog.value=true;try{detalleSeleccionado.value=await operacionesService.planilla(row.id)}catch(e){error.value=e.message;detailDialog.value=false}finally{cargandoDetalle.value=false}}
function irAlAsiento(id){detailDialog.value=false;router.push({path:'/libro-diario',query:{asiento_id:id}})}
function periodoPorAnio(anio){return periodos.value.find(p=>String(p.anio)===String(anio))}
function actualizarPeriodoPago(fecha){const anio=fecha?.slice(0,4);const periodo=periodoPorAnio(anio);payment.value.periodo_id=periodo?.id||null;paymentError.value=periodo?'':`No hay un período contable abierto para ${anio||'el año elegido'}. Abre ese período en Control antes de registrar el pago.`}
function abrirPago(row){error.value='';paymentError.value='';selectedPayroll.value=row;const periodo=String(row.periodo||'').slice(0,7);const anio=periodo.slice(0,4);payment.value={fecha_pago:periodo?`${periodo}-01`:'',periodo_id:periodoPorAnio(anio)?.id||null,cuenta_pago_codigo:'1.1.1.01'};if(!payment.value.periodo_id)paymentError.value=`No hay un período contable abierto para ${anio||'el año de la planilla'}. Abre ese período en Control antes de registrar el pago.`;paymentDialog.value=true}
async function guardarPago(){paymentError.value='';if(!selectedPayroll.value)return;if(payment.value.fecha_pago?.slice(0,7)!==String(selectedPayroll.value.periodo).slice(0,7)){paymentError.value=`La fecha de pago debe estar dentro de ${selectedPayroll.value.periodo}, el mes de esta planilla.`;return}if(!payment.value.periodo_id){paymentError.value=`No hay un período contable abierto para el año de la fecha de pago.`;return}guardando.value=true;try{const r=await operacionesService.pagarPlanilla(selectedPayroll.value.id,payment.value);paymentDialog.value=false;mensaje.value=`Asiento de pago ${r.asiento_codigo} pendiente de aprobación. Apruébalo en Control.`;await cargar()}catch(e){paymentError.value=`No se pudo registrar el pago de la planilla ${selectedPayroll.value.codigo}. ${e.message}`}finally{guardando.value=false}}
async function refrescarPlanillas(){if(document.visibilityState!=='visible'||cargando.value||guardando.value||enviando.value!==null||dialog.value||paymentDialog.value||detailDialog.value)return;try{const result=await operacionesService.planillas();planillas.value=result.planillas}catch(e){error.value=e.message}}
function refrescarAlVolver(){if(document.visibilityState==='visible')refrescarPlanillas()}
onMounted(()=>{cargar();refreshPlanillasTimer=window.setInterval(refrescarPlanillas,5000);window.addEventListener('focus',refrescarAlVolver);document.addEventListener('visibilitychange',refrescarAlVolver)})
onUnmounted(()=>{if(refreshPlanillasTimer)window.clearInterval(refreshPlanillasTimer);window.removeEventListener('focus',refrescarAlVolver);document.removeEventListener('visibilitychange',refrescarAlVolver)})
</script>
